sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amplitude;
uniform float wavelength;
uniform float direction;
uniform float speed;

half4 main(float2 coord) {
    float phase = time * speed;
    float rad = radians(direction);
    float2 dir = float2(cos(rad), sin(rad));
    float dist = dot(coord, dir);
    float offset = amplitude * sin(2.0 * 3.14 * dist / wavelength + phase);
    float2 warp = coord + offset * dir;
    half4 c = image.eval(warp);
    float a = c.a;
    if (a > 0.001) {
        c.rgb /= a;
    }
    c.rgb *= a;
    return c;
}
